effect.shader:
void main(){
    vec2 c = center/1000.0 + 0.5;
    vec2 dir = acScreenNorm - c;
    float d = pow(length(dir), falloff);
    vec2 off = dir * amount * d;
    float r = texture2DCv(inputImg.texture, acScreenNorm - off).r;
    vec4 g = texture2DCv(inputImg.texture, acScreenNorm);
    float b = texture2DCv(inputImg.texture, acScreenNorm + off).b;
    gl_FragColor = vec4(r, g.g, b, g.a);
}
